a.deleted = 0

    AND a.algorithm_name LIKE CONCAT('%', #{query.algorithmName}, '%')


    AND a.algorithm_code = #{query.algorithmCode}


    AND a.algorithm_type = #{query.algorithmType}


    AND a.media_type = #{query.mediaType}


    AND a.status = #{query.status}

mapper.select:
